class Solution {
public:
    long long minCost(vector<int>& arr, vector<int>& brr, long long k) {
        int n = arr.size();
        long long costNoReorder = 0;
        for (int i = 0; i < n; ++i) {
            costNoReorder += abs((long long)arr[i] - brr[i]);
        }

        vector<int> sArr = arr;
        vector<int> sBrr = brr;
        sort(sArr.begin(), sArr.end());
        sort(sBrr.begin(), sBrr.end());

        long long costReorder = k;
        for (int i = 0; i < n; ++i) {
            costReorder += abs((long long)sArr[i] - sBrr[i]);
        }
        return min(costNoReorder, costReorder);
    }
};

class Solution {
    public long minCost(int[] arr, int[] brr, long k) {
        int n = arr.length;
        long costNoReorder = 0;
        for (int i = 0; i < n; ++i) {
            costNoReorder += Math.abs((long)arr[i] - brr[i]);
        }

        int[] sArr = arr.clone();
        int[] sBrr = brr.clone();
        Arrays.sort(sArr);
        Arrays.sort(sBrr);

        long costReorder = k;
        for (int i = 0; i < n; ++i) {
            costReorder += Math.abs((long)sArr[i] - sBrr[i]);
        }
        return Math.min(costNoReorder, costReorder);
    }
}

var minCost = function(arr, brr, k) {
    const n = arr.length;
    let costNoReorder = 0n;
    for (let i = 0; i < n; ++i) {
        costNoReorder += BigInt(Math.abs(arr[i] - brr[i]));
    }

    const sArr = [...arr].sort((a, b) => a - b);
    const sBrr = [...brr].sort((a, b) => a - b);
    let costReorder = BigInt(k);
    for (let i = 0; i < n; ++i) {
        costReorder += BigInt(Math.abs(sArr[i] - sBrr[i]));
    }

    return Number(costNoReorder < costReorder ? costNoReorder : costReorder);
};
